                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @push('scripts')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <script>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (()=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const form=document.getElementById('adForm'); if(!form)return; let step=1; const sections=[...form.querySelectorAll('[data-step]')];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const syncType=()=>{const type=form.querySelector('input[name="type"]:checked')?.value||'product'; form.querySelectorAll('.product-only').forEach(el=>el.hidden=type!=='product'); form.querySelectorAll('.service-only').forEach(el=>el.hidden=type!=='service'); form.querySelectorAll('#category_id option[data-type]').forEach(o=>o.hidden=o.dataset.type!==type);};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const render=()=>{sections.forEach((s,i)=>s.hidden=i!==step-1);form.querySelectorAll('[data-step-indicator]').forEach((el,i)=>el.classList.toggle('is-active',i===step-1));document.getElementById('prevStep').hidden=step===1;document.getElementById('nextStep').hidden=step===3;document.getElementById('submitStep').hidden=step!==3;window.scrollTo({top:form.offsetTop-20,behavior:'smooth'});};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const currentSectionValid=()=>{const sec=sections[step-1]; const fields=[...sec.querySelectorAll('input,select,textarea')].filter(f=>!f.hidden && !f.closest('[hidden]')); for(const f of fields){if(!f.checkValidity()){f.reportValidity();return false;}} return true;};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                form.querySelectorAll('input[name="type"]').forEach(r=>r.addEventListener('change',syncType)); document.getElementById('nextStep').addEventListener('click',()=>{if(!currentSectionValid())return; if(step===1){const selectedType=form.querySelector('input[name="type"]:checked')?.value; if(selectedType==='service' && !@json($hasActiveServiceSubscription ?? false)){window.location.href='{{ route('service.plans') }}';return;} if(selectedType==='product' && !@json($hasActiveProductSubscription ?? false)){window.location.href='{{ route('product.plans') }}';return;}} if(step<3){step++;render();}}); document.getElementById('prevStep').addEventListener('click',()=>{if(step>1){step--;render();}}); form.addEventListener('submit',(e)=>{if(!currentSectionValid())e.preventDefault();}); syncType();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @if($errors->any())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (()=>{const errorFields=@json(array_keys($errors->toArray()));const stepOf={type:1,category_id:2,title:2,price:2,condition:2,brand:2,model:2,full_name:2,service_title:2,description:2,province_id:3,city_id:3,address:3,phone:3,card_number:3,website:3,images:3};for(const f of errorFields){if(stepOf[f]){step=stepOf[f];break;}}})();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @endif
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const province=document.getElementById('province'),city=document.getElementById('city'); province?.addEventListener('change',async e=>{city.innerHTML='<option value="">در حال بارگذاری...</option>'; if(!e.target.value){city.innerHTML='<option value="">شهر</option>';return;} try{const r=await fetch('{{ url('/api/cities') }}/'+e.target.value);const d=await r.json();city.innerHTML='<option value="">شهر</option>';d.forEach(x=>city.insertAdjacentHTML('beforeend',`<option value="${x.id}">${x.name}</option>`));}catch{city.innerHTML='<option value="">خطا در دریافت شهرها</option>';}});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const imagesInput=document.getElementById('images'),imagesLabelText=document.getElementById('imagesLabelText');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        imagesInput?.addEventListener('change',()=>{const n=imagesInput.files.length; imagesLabelText.textContent = n===0 ? 'برای انتخاب عکس کلیک کنید' : (n===1 ? imagesInput.files[0].name : n+' عکس انتخاب شد');});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </script>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                @endpush
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        